_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87ce9a12-c613-5d21-8977-a1796c73385d"}, {"title": "崔胤奏罢宦官掌兵预政、撤内诸司使与诸道监军，昭宗从之", "start_year": 903, "end_year": 903, "time_original": "903年正月庚午", "dynasty": "唐", "description": "崔胤奏罢宦官掌兵预政、撤内诸司使与诸道监军，昭宗从之。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6df9c26e-81d7-546b-809f-6d6a25824a2f"}, {"title": "朱全忠驱第五可范等宦官于内侍省尽杀", "start_year": 903, "end_year": 903, "time_original": "903年正月庚午", "dynasty": "唐", "description": "朱全忠驱第五可范等宦官于内侍省尽杀。", "phases": [], "location_name": "长安内侍省", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a598605f-56c2-5da6-9137-6ca7547354a5"}, {"title": "朝廷诏诸地捕杀外出宦官，仅留黄衣幼弱三十人", "start_year": 903, "end_year": 903, "time_original": "903年正月庚午后", "dynasty": "唐", "description": "朝廷诏诸地捕杀外出宦官，仅留黄衣幼弱三十人。", "phases": [], "location_name": "诸道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e87a9295-e558-580c-8ad7-fffffffdabb9"}, {"title": "昭宗诏王镕选五十人充敕使", "start_year": 903, "end_year": 903, "time_original": "903年本段条；确日未载", "dynasty": "唐", "description": "昭宗诏王镕选五十人充敕使。", "phases": [], "location_name": "成德、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e31b5dde-797c-5214-844a-e38f69d8bed9"}, {"title": "昭宗为可能无罪的第五可范等作祭文", "start_year": 903, "end_year": 903, "time_original": "903年本段条；确日未载", "dynasty": "唐", "description": "昭宗为可能无罪的第五可范等作祭文。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat":